// Generated by the website's scripts/build-peppol-ubl-check.ts from its own copy of these tests; edit there.
import { readFileSync } from "node:fs";
import { resolve } from "node:path";
import { describe, expect, it } from "vitest";
import { RULES } from "../src/engine/rules-catalog";
import { validateInvoiceXml } from "../src/engine/validate";

/**
 * The rules added in Peppol UBL check 1.4.0 and 1.5.0, held to the official artefacts' verdicts on
 * our own generated invoices (src/test/fixtures/schematron-parity, recorded with CEN 1.3.17 and
 * Peppol BIS 3.0.22 under Saxon). The official unit tests cover many of these rules for UBL only,
 * and Peppol's R041 (Norwegian numbers) only on orders; these invoices also cover CII and the
 * combinations the unit tests leave out.
 */

const DIR = resolve(__dirname, "fixtures/schematron-parity");

interface Recorded {
  rules: string[];
  cases: Record<string, Record<string, "error" | "warning">>;
}
const recorded = JSON.parse(readFileSync(resolve(DIR, "verdicts.json"), "utf8")) as Recorded;
const checked = new Set(recorded.rules);

/** Our verdicts for the recorded rules: the worst finding per rule (info doesn't count). */
function verdicts(xml: string): Record<string, "error" | "warning"> {
  const out: Record<string, "error" | "warning"> = {};
  for (const f of validateInvoiceXml(xml, "peppol").findings) {
    if (!checked.has(f.ruleId) || f.severity === "info") continue;
    if (out[f.ruleId] !== "error") out[f.ruleId] = f.severity === "error" ? "error" : "warning";
  }
  return Object.fromEntries(Object.entries(out).sort(([a], [b]) => a.localeCompare(b)));
}

describe("official verdicts on generated invoices", () => {
  it("records only rules the catalog has", () => {
    const ids = new Set(RULES.map((r) => r.id));
    expect(recorded.rules.filter((id) => !ids.has(id))).toEqual([]);
  });

  it("has invoices in both syntaxes, and each recorded rule fails in at least one", () => {
    const files = Object.keys(recorded.cases);
    expect(files.filter((f) => f.startsWith("ubl/")).length).toBeGreaterThan(20);
    expect(files.filter((f) => f.startsWith("cii/")).length).toBeGreaterThan(20);
    const failing = new Set(Object.values(recorded.cases).flatMap((v) => Object.keys(v)));
    // R080 (UBL credit notes only) and the code lists already held elsewhere need no failing case here
    const elsewhere = new Set(["BR-CL-04", "BR-CL-24", "PEPPOL-EN16931-CL001", "PEPPOL-EN16931-R080"]);
    expect(recorded.rules.filter((id) => !failing.has(id) && !elsewhere.has(id))).toEqual([]);
  });

  it.each(Object.entries(recorded.cases))("%s", (file, expected) => {
    const xml = readFileSync(resolve(DIR, file), "utf8");
    expect(verdicts(xml)).toEqual(expected);
  });
});
